#!/bin/bash\n\n# Environment Validation Script for AgentScan Deployment\n# Validates prerequisites, environment variables, and configuration\n\nset -euo pipefail\n\n# Script configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$(dirname \"$SCRIPT_DIR\")\")\"  # Go up two levels\nDEPLOYMENT_DIR=\"$PROJECT_ROOT/deployment\"\n\n# Default configuration\nENVIRONMENT=\"production\"\nPLATFORM=\"kubernetes\"\nVERBOSE=false\nFIX_ISSUES=false\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog_info() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nlog_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nlog_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nlog_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_verbose() {\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo -e \"${BLUE}[VERBOSE]${NC} $1\"\n    fi\n}\n\n# Function to show help\nshow_help() {\n    cat << EOF\nAgentScan Environment Validation Script\n\nUsage: $0 [OPTIONS]\n\nOptions:\n    --environment ENV    Environment to validate (default: production)\n    --platform PLATFORM Platform: kubernetes, docker, digitalocean (default: kubernetes)\n    --verbose           Enable verbose logging\n    --fix               Attempt to fix issues automatically\n    --help              Show this help message\n\nExamples:\n    $0 --platform kubernetes --verbose\n    $0 --environment staging --fix\n\nEOF\n}\n\n# Validation functions will be added in subsequent appends\n"# Function 
to validate system prerequisites\nvalidate_prerequisites() {\n    log_info \"Validating system prerequisites...\"\n    \n    local missing_tools=()\n    local version_issues=()\n    \n    # Common tools\n    local common_tools=(\"curl\" \"jq\" \"git\" \"openssl\")\n    for tool in \"${common_tools[@]}\"; do\n        if ! command -v \"$tool\" &> /dev/null; then\n            missing_tools+=(\"$tool\")\n        else\n            log_verbose \"Found: $tool\"\n        fi\n    done\n    \n    # Platform-specific tools\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Check kubectl\n            if ! command -v kubectl &> /dev/null; then\n                missing_tools+=(\"kubectl\")\n            else\n                local kubectl_version=$(kubectl version --client --output=json 2>/dev/null | jq -r '.clientVersion.gitVersion' || echo \"unknown\")\n                log_verbose \"kubectl version: $kubectl_version\"\n                \n                # Check kubectl connection\n                if ! kubectl cluster-info &> /dev/null; then\n                    version_issues+=(\"kubectl is not connected to a cluster\")\n                fi\n            fi\n            \n            # Check helm\n            if ! command -v helm &> /dev/null; then\n                missing_tools+=(\"helm\")\n            else\n                local helm_version=$(helm version --template='{{.Version}}' 2>/dev/null || echo \"unknown\")\n                log_verbose \"helm version: $helm_version\"\n            fi\n            ;;\n        \"docker\")\n            # Check docker\n            if ! command -v docker &> /dev/null; then\n                missing_tools+=(\"docker\")\n            else\n                local docker_version=$(docker --version | cut -d' ' -f3 | cut -d',' -f1)\n                log_verbose \"docker version: $docker_version\"\n                \n                # Check Docker daemon\n                if ! docker info &> /dev/null; then\n                    version_issues+=(\"Docker daemon is not running\")\n                fi\n            fi\n            \n            # Check docker-compose\n            if ! command -v docker-compose &> /dev/null; then\n                missing_tools+=(\"docker-compose\")\n            else\n                local compose_version=$(docker-compose --version | cut -d' ' -f3 | cut -d',' -f1)\n                log_verbose \"docker-compose version: $compose_version\"\n            fi\n            ;;\n        \"digitalocean\")\n            # Check doctl\n            if ! command -v doctl &> /dev/null; then\n                missing_tools+=(\"doctl\")\n            else\n                local doctl_version=$(doctl version | grep \"doctl version\" | cut -d' ' -f3)\n                log_verbose \"doctl version: $doctl_version\"\n                \n                # Check doctl authentication\n                if ! doctl account get &> /dev/null; then\n                    version_issues+=(\"doctl is not authenticated. Run: doctl auth init\")\n                fi\n            fi\n            ;;\n    esac\n    \n    # Report missing tools\n    if [[ ${#missing_tools[@]} -gt 0 ]]; then\n        log_error \"Missing required tools:\"\n        printf '  %s\\n' \"${missing_tools[@]}\"\n        \n        if [[ \"$FIX_ISSUES\" == \"true\" ]]; then\n            log_info \"Attempting to install missing tools...\"\n            install_missing_tools \"${missing_tools[@]}\"\n        fi\n        \n        return 1\n    fi\n    \n    # Report version issues\n    if [[ ${#version_issues[@]} -gt 0 ]]; then\n        log_error \"Tool configuration issues:\"\n        printf '  %s\\n' \"${version_issues[@]}\"\n        return 1\n    fi\n    \n    log_success \"Prerequisites validation passed\"\n    return 0\n}\n\n# Function to install missing tools\ninstall_missing_tools() {\n    local tools=(\"$@\")\n    \n    # Detect OS\n    local os=\"unknown\"\n    if [[ \"$OSTYPE\" == \"linux-gnu\"* ]]; then\n        os=\"linux\"\n    elif [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n        os=\"macos\"\n    fi\n    \n    log_info \"Detected OS: $os\"\n    \n    for tool in \"${tools[@]}\"; do\n        log_info \"Installing $tool...\"\n        \n        case \"$tool\" in\n            \"curl\")\n                if [[ \"$os\" == \"linux\" ]]; then\n                    sudo apt-get update && sudo apt-get install -y curl\n                elif [[ \"$os\" == \"macos\" ]]; then\n                    brew install curl\n                fi\n                ;;\n            \"jq\")\n                if [[ \"$os\" == \"linux\" ]]; then\n                    sudo apt-get update && sudo apt-get install -y jq\n                elif [[ \"$os\" == \"macos\" ]]; then\n                    brew install jq\n                fi\n                ;;\n            \"kubectl\")\n                if [[ \"$os\" == \"linux\" ]]; then\n                    curl -LO \"https://dl.k8s.io/release/$(curl -L -s https://dl.k8s.io/release/stable.txt)/bin/linux/amd64/kubectl\"\n                    sudo install -o root -g root -m 0755 kubectl /usr/local/bin/kubectl\n                elif [[ \"$os\" == \"macos\" ]]; then\n                    brew install kubectl\n                fi\n                ;;\n            \"helm\")\n                if [[ \"$os\" == \"linux\" ]]; then\n                    curl https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3 | bash\n                elif [[ \"$os\" == \"macos\" ]]; then\n                    brew install helm\n                fi\n                ;;\n            \"docker\")\n                log_warning \"Docker installation requires manual setup. Please visit: https://docs.docker.com/get-docker/\"\n                ;;\n            \"doctl\")\n                if [[ \"$os\" == \"linux\" ]]; then\n                    curl -sL https://github.com/digitalocean/doctl/releases/download/v1.94.0/doctl-1.94.0-linux-amd64.tar.gz | tar -xzv\n                    sudo mv doctl /usr/local/bin\n                elif [[ \"$os\" == \"macos\" ]]; then\n                    brew install doctl\n                fi\n                ;;\n            *)\n                log_warning \"Don't know how to install: $tool\"\n                ;;\n        esac\n    done\n}\n"# Func
tion to validate environment variables\nvalidate_environment_variables() {\n    log_info \"Validating environment variables...\"\n    \n    local missing_vars=()\n    local optional_vars=()\n    \n    # Common required variables\n    local common_required=(\"JWT_SECRET\")\n    \n    # Platform-specific variables\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            local k8s_vars=(\"KUBECONFIG\")\n            # KUBECONFIG is optional if ~/.kube/config exists\n            if [[ -z \"${KUBECONFIG:-}\" ]] && [[ ! -f \"$HOME/.kube/config\" ]]; then\n                missing_vars+=(\"KUBECONFIG (or ~/.kube/config file)\")\n            fi\n            ;;\n        \"digitalocean\")\n            local do_vars=(\"DO_TOKEN\")\n            for var in \"${do_vars[@]}\"; do\n                if [[ -z \"${!var:-}\" ]]; then\n                    missing_vars+=(\"$var\")\n                fi\n            done\n            ;;\n    esac\n    \n    # Check common required variables\n    for var in \"${common_required[@]}\"; do\n        if [[ -z \"${!var:-}\" ]]; then\n            missing_vars+=(\"$var\")\n        else\n            log_verbose \"Found: $var\"\n        fi\n    done\n    \n    # Check optional but recommended variables\n    local optional_recommended=(\"GITHUB_CLIENT_ID\" \"GITHUB_SECRET\" \"SUPABASE_URL\" \"SUPABASE_ANON_KEY\")\n    for var in \"${optional_recommended[@]}\"; do\n        if [[ -z \"${!var:-}\" ]]; then\n            optional_vars+=(\"$var\")\n        else\n            log_verbose \"Found: $var\"\n        fi\n    done\n    \n    # Report missing required variables\n    if [[ ${#missing_vars[@]} -gt 0 ]]; then\n        log_error \"Missing required environment variables:\"\n        printf '  %s\\n' \"${missing_vars[@]}\"\n        \n        if [[ \"$FIX_ISSUES\" == \"true\" ]]; then\n            log_info \"Attempting to generate missing variables...\"\n            generate_missing_variables \"${missing_vars[@]}\"\n        fi\n        \n        return 1\n    fi\n    \n    # Report missing optional variables\n    if [[ ${#optional_vars[@]} -gt 0 ]]; then\n        log_warning \"Missing optional environment variables:\"\n        printf '  %s\\n' \"${optional_vars[@]}\"\n        log_info \"These variables are optional but recommended for full functionality\"\n    fi\n    \n    log_success \"Environment variables validation passed\"\n    return 0\n}\n\n# Function to generate missing environment variables\ngenerate_missing_variables() {\n    local vars=(\"$@\")\n    \n    for var in \"${vars[@]}\"; do\n        case \"$var\" in\n            \"JWT_SECRET\")\n                log_info \"Generating JWT_SECRET...\"\n                local jwt_secret=$(openssl rand -base64 32)\n                echo \"export JWT_SECRET='$jwt_secret'\" >> \"$HOME/.bashrc\"\n                export JWT_SECRET=\"$jwt_secret\"\n                log_success \"Generated JWT_SECRET (added to ~/.bashrc)\"\n                ;;\n            *)\n                log_warning \"Don't know how to generate: $var\"\n                ;;\n        esac\n    done\n}\n\n# Function to validate configuration files\nvalidate_configuration_files() {\n    log_info \"Validating configuration files...\"\n    \n    local missing_files=()\n    local invalid_files=()\n    \n    # Platform-specific configuration files\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            local k8s_files=(\n                \"$DEPLOYMENT_DIR/k8s/namespace.yaml\"\n                \"$DEPLOYMENT_DIR/k8s/api-deployment.yaml\"\n                \"$DEPLOYMENT_DIR/k8s/orchestrator-deployment.yaml\"\n                \"$DEPLOYMENT_DIR/k8s/services.yaml\"\n            )\n            \n            for file in \"${k8s_files[@]}\"; do\n                if [[ ! -f \"$file\" ]]; then\n                    missing_files+=(\"$file\")\n                else\n                    log_verbose \"Found: $file\"\n                    \n                    # Validate YAML syntax\n                    if ! kubectl apply --dry-run=client -f \"$file\" &> /dev/null; then\n                        invalid_files+=(\"$file (invalid Kubernetes YAML)\")\n                    fi\n                fi\n            done\n            ;;\n        \"docker\")\n            local docker_files=(\n                \"$DEPLOYMENT_DIR/production/docker-compose.yml\"\n                \"$DEPLOYMENT_DIR/production/Dockerfile\"\n            )\n            \n            for file in \"${docker_files[@]}\"; do\n                if [[ ! -f \"$file\" ]]; then\n                    missing_files+=(\"$file\")\n                else\n                    log_verbose \"Found: $file\"\n                    \n                    # Validate docker-compose syntax\n                    if [[ \"$file\" == *\"docker-compose.yml\" ]]; then\n                        if ! docker-compose -f \"$file\" config &> /dev/null; then\n                            invalid_files+=(\"$file (invalid Docker Compose syntax)\")\n                        fi\n                    fi\n                fi\n            done\n            ;;\n        \"digitalocean\")\n            local do_files=(\n                \"$DEPLOYMENT_DIR/digitalocean/app.yaml\"\n            )\n            \n            for file in \"${do_files[@]}\"; do\n                if [[ ! -f \"$file\" ]]; then\n                    missing_files+=(\"$file\")\n                else\n                    log_verbose \"Found: $file\"\n                    \n                    # Validate app spec\n                    if command -v doctl &> /dev/null; then\n                        if ! doctl apps spec validate \"$file\" &> /dev/null; then\n                            invalid_files+=(\"$file (invalid DigitalOcean app spec)\")\n                        fi\n                    fi\n                fi\n            done\n            ;;\n    esac\n    \n    # Report missing files\n    if [[ ${#missing_files[@]} -gt 0 ]]; then\n        log_error \"Missing configuration files:\"\n        printf '  %s\\n' \"${missing_files[@]}\"\n        return 1\n    fi\n    \n    # Report invalid files\n    if [[ ${#invalid_files[@]} -gt 0 ]]; then\n        log_error \"Invalid configuration files:\"\n        printf '  %s\\n' \"${invalid_files[@]}\"\n        return 1\n    fi\n    \n    log_success \"Configuration files validation passed\"\n    return 0\n}\n"# Functio
n to validate network connectivity\nvalidate_network_connectivity() {\n    log_info \"Validating network connectivity...\"\n    \n    local connectivity_issues=()\n    \n    # Test basic internet connectivity\n    if ! curl -s --max-time 10 https://www.google.com > /dev/null; then\n        connectivity_issues+=(\"No internet connectivity\")\n    else\n        log_verbose \"Internet connectivity: OK\"\n    fi\n    \n    # Platform-specific connectivity tests\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Test Kubernetes API server connectivity\n            if command -v kubectl &> /dev/null; then\n                if ! kubectl cluster-info &> /dev/null; then\n                    connectivity_issues+=(\"Cannot connect to Kubernetes cluster\")\n                else\n                    log_verbose \"Kubernetes cluster connectivity: OK\"\n                fi\n            fi\n            \n            # Test Docker registry connectivity\n            if ! curl -s --max-time 10 https://registry-1.docker.io > /dev/null; then\n                connectivity_issues+=(\"Cannot connect to Docker Hub registry\")\n            else\n                log_verbose \"Docker Hub registry connectivity: OK\"\n            fi\n            ;;\n        \"docker\")\n            # Test Docker daemon connectivity\n            if command -v docker &> /dev/null; then\n                if ! docker info &> /dev/null; then\n                    connectivity_issues+=(\"Cannot connect to Docker daemon\")\n                else\n                    log_verbose \"Docker daemon connectivity: OK\"\n                fi\n            fi\n            ;;\n        \"digitalocean\")\n            # Test DigitalOcean API connectivity\n            if ! curl -s --max-time 10 https://api.digitalocean.com > /dev/null; then\n                connectivity_issues+=(\"Cannot connect to DigitalOcean API\")\n            else\n                log_verbose \"DigitalOcean API connectivity: OK\"\n            fi\n            ;;\n    esac\n    \n    # Test GitHub connectivity (for source code)\n    if ! curl -s --max-time 10 https://api.github.com > /dev/null; then\n        connectivity_issues+=(\"Cannot connect to GitHub API\")\n    else\n        log_verbose \"GitHub API connectivity: OK\"\n    fi\n    \n    # Report connectivity issues\n    if [[ ${#connectivity_issues[@]} -gt 0 ]]; then\n        log_error \"Network connectivity issues:\"\n        printf '  %s\\n' \"${connectivity_issues[@]}\"\n        return 1\n    fi\n    \n    log_success \"Network connectivity validation passed\"\n    return 0\n}\n\n# Function to validate resource requirements\nvalidate_resource_requirements() {\n    log_info \"Validating system resource requirements...\"\n    \n    local resource_issues=()\n    \n    # Check available disk space\n    local available_space=$(df / | awk 'NR==2 {print $4}')\n    local required_space=5242880  # 5GB in KB\n    \n    if [[ $available_space -lt $required_space ]]; then\n        resource_issues+=(\"Insufficient disk space: ${available_space}KB available, ${required_space}KB required\")\n    else\n        log_verbose \"Disk space: OK (${available_space}KB available)\"\n    fi\n    \n    # Check available memory\n    if command -v free &> /dev/null; then\n        local available_memory=$(free -k | awk 'NR==2 {print $7}')\n        local required_memory=2097152  # 2GB in KB\n        \n        if [[ $available_memory -lt $required_memory ]]; then\n            resource_issues+=(\"Insufficient memory: ${available_memory}KB available, ${required_memory}KB required\")\n        else\n            log_verbose \"Memory: OK (${available_memory}KB available)\"\n        fi\n    elif [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n        # macOS memory check\n        local total_memory=$(sysctl -n hw.memsize)\n        local total_memory_gb=$((total_memory / 1024 / 1024 / 1024))\n        \n        if [[ $total_memory_gb -lt 4 ]]; then\n            resource_issues+=(\"Insufficient memory: ${total_memory_gb}GB total, 4GB recommended\")\n        else\n            log_verbose \"Memory: OK (${total_memory_gb}GB total)\"\n        fi\n    fi\n    \n    # Platform-specific resource checks\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Check if cluster has sufficient resources\n            if command -v kubectl &> /dev/null && kubectl cluster-info &> /dev/null; then\n                local node_count=$(kubectl get nodes --no-headers 2>/dev/null | wc -l || echo \"0\")\n                if [[ $node_count -eq 0 ]]; then\n                    resource_issues+=(\"No Kubernetes nodes available\")\n                else\n                    log_verbose \"Kubernetes nodes: $node_count available\"\n                fi\n            fi\n            ;;\n        \"docker\")\n            # Check Docker daemon resources\n            if command -v docker &> /dev/null && docker info &> /dev/null; then\n                local docker_info=$(docker system df --format \"table {{.Type}}\\t{{.Size}}\" 2>/dev/null || echo \"\")\n                log_verbose \"Docker system info available\"\n            fi\n            ;;\n    esac\n    \n    # Report resource issues\n    if [[ ${#resource_issues[@]} -gt 0 ]]; then\n        log_error \"System resource issues:\"\n        printf '  %s\\n' \"${resource_issues[@]}\"\n        return 1\n    fi\n    \n    log_success \"Resource requirements validation passed\"\n    return 0\n}\n\n# Main validation function\nmain_validation() {\n    log_info \"Starting environment validation for platform: $PLATFORM\"\n    log_info \"Environment: $ENVIRONMENT\"\n    \n    local validation_errors=0\n    \n    # Run all validations\n    if ! validate_prerequisites; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_environment_variables; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_configuration_files; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_network_connectivity; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_resource_requirements; then\n        ((validation_errors++))\n    fi\n    \n    # Summary\n    echo \"\"\n    log_info \"Validation Summary\"\n    echo \"==================\"\n    \n    if [[ $validation_errors -eq 0 ]]; then\n        log_success \"All validations passed! Environment is ready for deployment.\"\n        exit 0\n    else\n        log_error \"$validation_errors validation(s) failed. Please fix the issues above.\"\n        \n        if [[ \"$FIX_ISSUES\" == \"true\" ]]; then\n            log_info \"Some issues may have been automatically fixed. Please re-run validation.\"\n        else\n            log_info \"Use --fix flag to attempt automatic fixes for some issues.\"\n        fi\n        \n        exit 1\n    fi\n}\n\n# Parse command line arguments\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        --environment)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --platform)\n            PLATFORM=\"$2\"\n            shift 2\n            ;;\n        --verbose)\n            VERBOSE=true\n            shift\n            ;;\n        --fix)\n            FIX_ISSUES=true\n            shift\n            ;;\n        --help|-h)\n            show_help\n            exit 0\n            ;;\n        *)\n            log_error \"Unknown option: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\ndone\n\n# Make script executable\nchmod +x \"$0\"\n\n# Run main validation\nmain_validation\n"